    workspace().innerHTML=`${listHead('Supplier chats','Reply to buyers and review the complete conversation history for every supplier.',false)}${unavailableNotice()}<div class="chat-toolbar"><label class="search"><input data-chat-filter placeholder="Search supplier, buyer, or message" aria-label="Search supplier chats"></label><span class="chat-count" data-chat-count>${cache.chats.length} conversation${cache.chats.length===1?'':'s'}</span></div><section class="panel chats-layout"><aside class="chat-list" aria-label="Supplier conversations" data-chat-list>${chatList(cache.chats)}</aside><section class="chat-thread" aria-live="polite" data-chat-thread>${activeChatId?'<div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div>':chatEmpty()}</section></section>`;
