  function chatList(rows){return rows.length?rows.map(chat=>`<button class="chat-row${String(chat.conversation_id)===String(activeChatId)?' is-selected':''}" data-chat-id="${esc(chat.conversation_id)}"><span class="chat-avatar" aria-hidden="true">${esc(String(chat.supplier_name||'?').slice(0,1).toUpperCase())}</span><span class="chat-row-copy"><strong>${esc(chat.supplier_name||'Supplier')}</strong><span>${esc(chat.buyer_name||chat.buyer_email||'Buyer')}</span><small>${esc(chat.last_message||'No messages yet')}</small></span><span class="chat-row-meta"><small>${esc(fmtDate(chat.last_message_at||chat.created_at))}</small><b>${esc(chat.message_count||0)}</b></span></button>`).join(''):tableEmpty('▰','No supplier chats','Buyer conversations will appear here when a sourcing inquiry is started.');}
  function chatEmpty(){return `<div class="empty"><div class="empty-symbol">▰</div><h2>Select a conversation</h2><p>Choose a supplier chat to review its history and reply as ${esc(currentProfile?.name||'the administrator')}.</p></div>`;}
  function filterChats(){const query=workspace().querySelector('[data-chat-filter]').value.trim().toLowerCase();const rows=cache.chats.filter(chat=>[chat.supplier_name,chat.buyer_name,chat.buyer_email,chat.last_message].some(value=>String(value||'').toLowerCase().includes(query)));workspace().querySelector('[data-chat-list]').innerHTML=chatList(rows);workspace().querySelector('[data-chat-count]').textContent=`${rows.length} conversation${rows.length===1?'':'s'}`;bindChatRows();}
  function bindChatRows(){workspace().querySelectorAll('[data-chat-id]').forEach(row=>row.onclick=()=>loadChat(row.dataset.chatId));}
  async function loadChat(id){
    activeChatId=id;workspace().querySelectorAll('[data-chat-id]').forEach(row=>row.classList.toggle('is-selected',row.dataset.chatId===String(id)));
    const thread=workspace().querySelector('[data-chat-thread]');if(!thread)return;thread.innerHTML='<div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div>';
    try{const result=await callFirst(['intoolsGetSupplierChat'],id);const chat=result.result?.chat||result.result;if(!chat?.conversation)throw new Error('Conversation could not be loaded.');thread.innerHTML=chatThread(chat);bindChatComposer(chat.conversation.id);}
    catch(error){thread.innerHTML=`<div class="notice notice-danger" role="alert"><span>!</span><div><strong>Could not load conversation</strong><p>${esc(error.message||'Try again.')}</p><button class="btn btn-secondary" data-chat-retry>Retry</button></div></div>`;thread.querySelector('[data-chat-retry]').onclick=()=>loadChat(id);}
  }
  function chatThread(chat){const c=chat.conversation,messages=chat.messages||[];return `<header class="chat-thread-head"><div><h2>${esc(c.supplier_name||'Supplier')}</h2><p>${esc(c.buyer_name||c.buyer_email||'Buyer')}${c.buyer_company?` · ${esc(c.buyer_company)}`:''}${c.buyer_email?` · ${esc(c.buyer_email)}`:''}</p></div><span class="badge">${messages.length} message${messages.length===1?'':'s'}</span></header><div class="chat-messages" data-chat-messages>${messages.length?messages.map(message=>{const isBuyer=String(message.sender_profile_id)===String(c.buyer_profile_id),isAdmin=String(message.sender_profile_id)===String(currentProfile?.id),role=isBuyer?'Buyer':(isAdmin?'Atelix team':'Supplier'),name=message.sender_name||message.sender_email||'Participant';return `<article class="chat-message${isAdmin?' is-admin':''}"><div class="chat-message-meta"><strong>${esc(role+' · '+name)}</strong><time datetime="${esc(message.created_at||'')}">${esc(fmtDate(message.created_at))}</time></div><p>${esc(message.body)}</p></article>`;}).join(''):`<div class="empty"><h2>No messages yet</h2><p>Send the first reply to this supplier conversation.</p></div>`}</div><form class="chat-composer" data-chat-form><label class="field"><span>Reply to ${esc(c.buyer_name||'this conversation')}</span><textarea name="body" rows="3" maxlength="4000" placeholder="Write a clear sourcing response…" required></textarea></label><div class="chat-composer-foot"><span class="field-help">Replies are sent as ${esc(currentProfile?.email||'the authorized administrator')}.</span><button class="btn btn-primary" type="submit">Send reply</button></div></form>`;}
  function bindChatComposer(id){const form=workspace().querySelector('[data-chat-form]');form.addEventListener('submit',async event=>{event.preventDefault();if(!form.reportValidity())return;const button=form.querySelector('button'),body=form.body.value.trim();button.disabled=true;button.textContent='Sending…';try{const result=await callFirst(['intoolsSendSupplierChatMessage'],id,body);if(!result.available)throw new Error('Chat replies are not available in this environment.');const sent=result.result?.message||result.result;const item=cache.chats.find(chat=>String(chat.conversation_id)===String(id));if(item){item.last_message=sent.body;item.last_message_at=sent.created_at;item.message_count=Number(item.message_count||0)+1;}toast('Reply sent.');await loadChat(id);filterChats();}catch(error){button.disabled=false;button.textContent='Send reply';toast(error.message||'Reply could not be sent.',true);}});}

