    const saveDraft=async()=>{if(!form.reportValidity())return null;const data=payload();if(!data.audience.roles.length){toast('Choose at least one opted-in audience.',true);return null;}const result=await callFirst(['intoolsSaveNotificationCampaign'],{id:campaign.id||null,payload:data});const saved=result.result?.campaign||result.result;if(!saved)throw new Error('Campaign could not be saved.');campaign=saved;cache.campaigns=[saved,...cache.campaigns.filter(item=>String(item.id)!==String(saved.id))];send.disabled=false;toast('Campaign draft saved.');return saved;};
